mapper.update:
UPDATE notice
SET view_count = view_count + 1
WHERE notice_id = #{notice_id}

UPDATE notice
SET title = #{title}, content = #{content}, status = #{status}, updated = SYSDATE
WHERE notice_id = #{notice_id}

UPDATE notice
SET deleted = SYSDATE
WHERE notice_id = #{notice_id}
  AND (
      member_id = #{requester_member_id}

      OR EXISTS (
          SELECT 1 
          FROM workspace_members wm 
          WHERE wm.workspace_id = notice.workspace_id 
            AND wm.member_id = #{requester_member_id} 
            AND wm.role = 70
      )


      OR EXISTS (
          SELECT 1 
          FROM project_members pm 
          WHERE pm.project_id = notice.project_id 
            AND pm.member_id = #{requester_member_id} 
            AND pm.role = 70
      )
  )
